"""
HIH flagship guides, source of truth until they are saved as Shopify drafts.
Shape follows the Guide contract in hih-guide-writer.
Media tokens: src="hih-media://<file-stem>" are replaced by Shopify CDN URLs at push time (scripts/push_guides.py).
"""

def step(title, body, fig=None):
    return {"title": title, "body": body, "fig": fig}

def fig(stem, alt, caption):
    return {"stem": stem, "alt": alt, "caption": caption}

