# 5 ─────────────────────────────────────────────────────────────── Plumbing
{
 "blog": "plumbing", "blog_title": "Plumbing Basics",
 "handle": "how-to-fix-a-running-toilet",
 "title": "How to Fix a Running Toilet",
 "summary": "Find out why your toilet keeps running with a 10-minute dye test, then fix the flapper, chain or fill valve yourself with basic tools.",
 "tags": ["Beginner", "Plumbing", "Toilet", "Under 1 hour"],
 "difficulty": "Beginner", "time": "30–60 minutes", "cost": "$5–$30",
 "tools": ["Sponge", "Bucket", "Adjustable pliers", "Flashlight"],
 "materials": ["Food coloring", "Replacement flapper matching your flush valve (2 in or 3 in)", "Replacement fill valve (if needed)"],
 "video": "https://www.youtube.com/watch?v=7ePc9cz__FM",
 "intro": "A running toilet can waste hundreds of gallons a day, and the fix is almost always one of three cheap parts inside the tank: the flapper, the chain, or the fill valve. Diagnose first, then replace only what's actually wrong.",
 "safety": "<strong>Safety:</strong> tank water is clean, but set the lid somewhere it can't fall. It's heavy and porcelain cracks. Turn supply valves gently. If the shut-off under the toilet won't turn or starts leaking, stop and use your home's main shut-off.",
 "steps": [
  step("Get to know the tank", "<p>Lift the lid. The fill valve (left) refills the tank and shuts off when its float rises. The overflow tube (center) drains excess water into the bowl. The flapper (bottom) seals the flush valve and lifts on a chain when you flush.</p><p><strong>Done right:</strong> you can point to the fill valve, float, overflow tube, flapper and chain.</p>",
       fig("how-to-fix-a-running-toilet-step-1", "Labeled diagram of a toilet tank showing fill valve, float, overflow tube, flapper, chain and water line", "The water line should sit about 1 in below the top of the overflow tube.")),
  step("Run the dye test", "<p>Add a few drops of food coloring to the tank and don't flush for 15–20 minutes. If color appears in the bowl, water is leaking past the flapper. If not, but the toilet still refills by itself, water is probably spilling into the overflow tube from a fill valve set too high.</p><p><strong>Done right:</strong> you know whether you have a flapper problem or a fill-level problem.</p>"),
  step("Check the water level", "<p>Look at the water against the overflow tube. If it's running over the top, lower the float by turning the adjustment screw or sliding the clip on the fill valve's float, until the level settles about 1 in below the top of the tube or at the mark inside the tank.</p><p><strong>Done right:</strong> after a flush, the water stops below the top of the overflow tube and stays there.</p>"),
  step("Adjust the chain", "<p>A chain that's too tight holds the flapper open slightly. One that's too long can get caught under it. With the flapper closed, the chain should have about 1/2 in of slack.</p><p><strong>Done right:</strong> the flapper drops cleanly and seats flat every time you flush.</p>"),
  step("Replace a worn flapper", "<p>Shut off the supply valve and flush to drain the tank. Unhook the chain, slide the flapper's ears off the pegs on the overflow tube, and take it to the store so you can match the size (2 in or 3 in) and style. Install the new flapper, hook the chain with the right slack, and turn the water back on.</p><p><strong>Done right:</strong> the dye test now shows no color in the bowl.</p>"),
  step("Replace the fill valve if it still runs", "<p>If the fill valve hisses, refills constantly or won't shut off at the right level, replace it. Shut off the water, drain and sponge the tank dry, disconnect the supply line, and unscrew the locknut under the tank. Set the new fill valve to the height in its instructions, tighten the locknut hand-tight plus a quarter turn, then reconnect and test.</p><p><strong>Done right:</strong> the tank fills to the right level, shuts off cleanly, and nothing drips under the tank.</p>"),
 ],
 "pro": "<strong>Call a plumber if:</strong> the shut-off valve leaks or won't turn, water is leaking where the tank meets the bowl, or the flush valve seat itself is cracked. Those mean taking the tank off.",
 "faq": [
  ("How much water does a running toilet waste?", "A steady leak can waste hundreds of gallons a day, often enough to show up on your water bill."),
  ("Why does my toilet run every few minutes on its own?", "That's a slow leak past the flapper (called phantom flushing). The tank slowly drains into the bowl until the fill valve kicks on to top it up. The dye test confirms it."),
  ("Are universal flappers really universal?", "Not quite. Flappers come in 2 in and 3 in sizes and several mounting styles, and some brands use their own designs. Bring the old one to the store to compare."),
  ("Should I replace the flapper and fill valve together?", "Only if both are worn. They're cheap, so replacing both on an older toilet saves a second trip, but diagnose first."),
 ],
},
